class _EmergencyResponsePageState extends State<EmergencyResponsePage> {
  String event = '';
  List<String> intentions = [];

  void setEventAndIntentions(String givenEvent, String givenIntention) {
    setState(() {
      event = givenEvent;
      intentions = [givenIntention];
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Emergency Response'),
      ),
      body: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const SizedBox(height: 16),
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16),
            child: Text(
              'What happened? ',
              style: Theme.of(context).textTheme.titleLarge,
            ),
          ),
          const SizedBox(height: 16),
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16),
            child: DropdownButton(
              value: event,
              hint: const Text('Select an event'),
              items: [
                const DropdownMenuItem(
                  value: '',
                  child: Text('Select an event'),
                ),
                DropdownMenuItem(
                  value: 'PersonX walked on PersonX ___',
                  child: Text('PersonX stepped on PersonX ___'),
                ),
                DropdownMenuItem(
                  value:
                      'PersonX holds ___ in place',
                  child: Text('PersonX holds ___ in place'),
                ),
                DropdownMenuItem(
                  value: 'PersonX hears sirens',
                  child: Text('PersonX hears sirens'),
                ),
              ],
              onChanged: (value) {
                setState(() {
                  event = value!;
                });
              },
            ),
          ),
          const SizedBox(height: 16),
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16),
            child: Text(
              'What was their intention? ',
              style: Theme.of(context).textTheme.titleLarge,
            ),
          ),
          const SizedBox(height: 16),
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16),
            child: DropdownButtonFormField(
              value: intentions.isEmpty ? '' : intentions[0],
              hint: const Text('Select an intention'),
              items: [
                const DropdownMenuItem(
                  value: '',
                  child: Text('Select an intention'),
                ),
                DropdownMenuItem(
                  value: 'to release his/her anger',
                  child: Text('to release his/her anger'),
                ),
                DropdownMenuItem(
                  value: 'to be organized',
                  child: Text('to be organized'),
                ),
              ],
              onChanged: (value) {
                if (value != '') {
                  setState(() {
                    intentions = [value];
                  });
                }
              },
            ),
          ),
          const SizedBox(height: 16),
          Expanded(
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 16),
              child: Text.rich(
                TextSpan(
                  style: Theme.of(context).textTheme.titleMedium,
                  children: [
