    val cleanedBusinessData: RDD[DenseVector[Double]] = businessData
      // Parse and fill missing values
      .map(parseArrayWithMissingValues)
      // Normalize data (optional)
      .map(normalizeData)

    // 3. Compute PCA and extract top n components
    val (explainedVariance, transformedData): (Array[Double], RDD[DenseVector[Double]]) = cleanedBusinessData
      // Compute SVD to get top n components
      .rdd
      .map(DenseVector(_))
      .map { vector =>
        val (singularValues, leftSingularVectors, rightSingularVectors) = svd(vector)
        (singularValues, leftSingularVectors)
      }
      .reduce { case ((singularValues1, leftSingularVectors1), (singularValues2, leftSingularVectors2)) =>
        (
          hstack(singularValues1, singularValues2),
          hadamard(hstack(leftSingularVectors1, leftSingularVectors2), sqrt(2.0))
        )
      }
      .map { case (singularValues, leftSingularVectors) =>
        val nTopComponents = findTopNComponents(singularValues)
        (nTopComponents, leftSingularVectors)
