  private def parseArrayWithMissingValues(array: Array[Double]): DenseVector[Double] = {
    array
      .map(parseDouble(_))
      .foldLeft(DenseVector.zeros[Double](array.length)) { case (acc, result) =>
        result match {
          case Success(value) => acc.updated(Array.indexOf(acc, null), value)
          case _ => acc
        }
      }
  }

  private def normalizeData(vector: DenseVector[Double]): DenseVector[Double] = {
    val mean = vector.mean
    val std = vector.std
    DenseVector((vector - mean) / std)
