                {"Маргаритка", "Da"},
                {"Бархатцы", "Ma"},
                {"Хризантема", "Ch"}
            })
                    .filter(arr -> arr[1].equals(prefix))
                    .map(arr -> arr[0])
                    .findFirst().orElse("Others");
        }
        return "Others";
    }
}
