    static bool emotionsContains(string input, string emotion, string[] synonyms) {
        bool found = false;
        if (input == emotion) {
            found = true;
        } else {
            foreach (string synonym in synonyms) {
                if (input.Contains(synonym, StringComparison.OrdinalIgnoreCase)) {
                    found = true;
                    break;
                }
            }
        }
        return found;
    }
}
