                    console.writeline("чувство, о котором вы думаете, — это меланхолия.");
                    break;

                case "saudade":
                    console.writeline("чувство, о котором вы думаете, — это саудаде.");
                    break;

                case "ekstase":
                    console.writeline("чувство, о котором вы думаете, — это экстаз.");
                    break;

                case "ennuyance":
                    console.writeline("чувство, о котором вы думаете, — это утомленность.");
                    break;

                default:
                    console.writeline("извините, я не знакома с этим чувством. Можете ли вы предоставить больше информации?");
                    break;
            }
        }
    }
}
```

с этим кодом, ваша программа будет принимать в качестве ввода название определенного чувства от пользователя и печатать соответствующую информацию о нем. Естественно, вы можете расширить программу, добавляя новые наименования для определенных чувств, изменяя условие `default` в соответствии с вашими потребностями.

