   ```C#
   // Import required namespaces
   using Axis.Vapi.X-device;
   using System;

   namespace CameraControl
   {
       class Program
       {
           static void Main(string[] args)
           {
               // Replace "INSTANCE_ID" and "PASSWORD" with your camera's Instance ID and password
               string instanceId = "INSTANCE_ID";
               string password = "PASSWORD";

               // Create camera object and attempt to connect to the Axis camera
               XDevice cam = new XDevice();
               cam.ConnectToAxisDevice(string.Format("http://{0}:80/axis-cgi/admin/intrantcp.cgi", instanceId), password);

               // Set video stream profile
               cam.SetVideoStreamProfile(StreamProfileType.MJPEG);

               // Get camera image
               Image image = cam.RetrieveImage();

               // Display camera image
               image.Display();

               // Disconnect from the camera
